  return r.json();
}
export const tok=t;
export const D_=D;
if(process.argv[2]){
  const o=await a2a(JSON.parse(process.argv[2]));
  console.log(JSON.stringify(o,null,1).slice(0,+process.argv[3]||6000));
}
EOF
