cd D:/paypal/join/examples; cat > done2-luis-auto.mjs <<'EOF'
import {a2a} from './done2-luis-a2a.mjs';
const g=async(x)=>(await a2a(x)).result?.parts?.[0]?.data;
const seen=new Set(['job_be2b624083','job_cf02d1f17c','job_02a6f52868','job_83600fd4fd','job_840047fe51','job_a9c9bf78cc']);
const log=(...a)=>console.log(new Date().toISOString().slice(11,19),...a);
const end=Date.now()+ +(process.argv[2]||600)*1000;
while(Date.now()<end){
  const d=await g({action:'list_jobs'});
  for(const j of d?.jobs||[]){ if(seen.has(j.id))continue; seen.add(j.id);
    const ceil=j.priceCeiling.cents/100; log('NEW',j.id,j.number,j.zip,ceil,j.title);
    if(!/faucet|drain|clog|leak|sink|toilet/i.test(j.title)) continue;
    const isFaucet=/faucet/i.test(j.title);
    const amt=Math.min(ceil, isFaucet?(ceil>=215?215:195):(ceil>=195?195:ceil));
    const o=await g({action:'offer',job:j.id,amount:amt,note:`Licensed master plumber M-41877, insured ($1M). $85 call-out + $110/hour, parts at cost: if a part beyond the basics is needed I send a change order with a photo before buying it. I can show every done-condition with photos taken on site.`});
    log('OFFER',j.id,amt,JSON.stringify(o).slice(0,300));
  }
  await new Promise(r=>setTimeout(r,3000));
}
EOF
